13	    public static int indexOf(int[] sortedValues, int target) {
14	        Objects.requireNonNull(sortedValues, "sortedValues");
15	
16	        int low = 0;
17	        int high = sortedValues.length - 1;
18	
19	        while (low <= high) {
20	            int mid = midpoint(low, high);
21	            int value = sortedValues[mid];
22	
23	            if (value == target) {
24	                return mid;
25	            }
26	
27	            if (value < target) {
28	                low = mid + 1;
29	            } else {
30	                high = mid - 1;
31	            }
32	        }
33	
34	        return NOT_FOUND;
35	    }
36	
37	    private static int midpoint(int low, int high) {
38	        return low + (high - low) / 2;
39	    }
40	}

